def comps(g,color):
    g=np.array(g); seen=np.zeros_like(g,bool); out=[]
    for r in range(g.shape[0]):
        for c in range(g.shape[1]):
            if g[r,c]==color and not seen[r,c]:
                st=[(r,c)]; seen[r,c]=True; cells=[]
                while st:
                    a,b=st.pop(); cells.append((a,b))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+dr,b+dc
                        if 0<=x<g.shape[0] and 0<=y<g.shape[1] and g[x,y]==color and not seen[x,y]:
                            seen[x,y]=True; st.append((x,y))
                out.append(cells)
    return out
