    for c in Ci: gr[c['norm']].append(c)
    dupcols={c['col'] for v in gr.values() if len(v)>1 for c in v}
    uniq=[c for c in Ci if c['col'] not in dupcols]
    cand={}
    for c in uniq:
        colsizes=[cc['size'] for cc in Ci if cc['col']==c['col']]
        cand[c['col']]=sum(colsizes)
    tgt=max(cand,key=cand.get)
    best=[v for v in gr.values() if len(v)>1]
    big=max(best,key=lambda v:max(cc['size'] for cc in v))
    chg=max(big,key=lambda c:min(r for r,_ in c['cells']))
    out=[row[:] for row in g]
    for r,cc in chg['cells']:
        out[r][cc]=tgt
    return out
