def comps_of(g):
    bg=g[0][0]; H,W=len(g),len(g[0])
    seen=[[False]*W for _ in range(H)]; out=[]
    for r in range(H):
        for c in range(W):
            if not seen[r][c] and g[r][c]!=bg:
                st=[(r,c)]; seen[r][c]=True; cells=[]; col=g[r][c]
                while st:
                    a,b=st.pop(); cells.append((a,b))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+dr,b+dc
                        if 0<=x<H and 0<=y<W and g[x][y]==col and not seen[x][y]:
                            seen[x][y]=True; st.append((x,y))
                rs=[p for p,_ in cells]; cs=[q for _,q in cells]
                norm=tuple(sorted((rr-min(rs),cc-min(cs)) for rr,cc in cells))
                onT=any(p==0 for p,_ in cells); onB=any(p==H-1 for p,_ in cells)
                onL=any(c2==0 for _,c2 in cells); onR=any(c2==W-1 for _,c2 in cells)
                out.append({'col':col,'cells':set(cells),'norm':norm,'size':len(cells),
                             'onT':onT,'onB':onB,'onL':onL,'onR':onR})
    return out
